// 07: Voting Age Checker
वद "Check your voting eligibility:"
पृच्छ आयु-मध्ये

यदि ( आयु > १७ ) {
    वद "Congratulations, you can vote!"
} तर्हि {
    वद "Sorry, you are too young to vote."
}

// 08: Secret Password Door
वद "Enter the secret password:"
पृच्छ पास-मध्ये

यदि ( पास == "Panini" ) {
    वद "Access Granted! Welcome inside."
} तर्हि {
    वद "Wrong Password. Access Denied!"
}

// 09: Rocket Launch Countdown
१० समय-मध्ये स्थापय
वद "Starting Rocket Countdown..."

यावत् ( समय > ० ) {
    वद समय
    समय १ न्यूनय समय-मध्ये
}

वद "Blastoff!!!"

// 10: Simple Counter
१ गिनती-मध्ये स्थापय
वद "Counting to 5..."

यावत् ( गिनती < ६ ) {
    वद गिनती
    गिनती १ संयोजय गिनती-मध्ये
}

वद "Done!"

// 11: Theme Park Ticket Pricing
वद "Welcome to the Ticket Machine."
पृच्छ आयु-मध्ये

यदि ( आयु < ५ ) {
    वद "Ticket is FREE for kids under 5!"
} तर्हि {

    यदि ( आयु < १८ ) {
        वद "Ticket is 50 Rupees for students."
    } तर्हि {
        वद "Ticket is 100 Rupees for adults."
    }

}

// 12: Factorial Calculator
वद "Enter a number to find its factorial:"
पृच्छ अंक-मध्ये
१ परिणाम-मध्ये स्थापय

यावत् ( अंक > ० ) {
    परिणाम अंक गुणय परिणाम-मध्ये
    अंक १ न्यूनय अंक-मध्ये
}
वद "The Factorial is: " परिणाम

// 13: Daily Labour Wage & Overtime Calculator
वद "Enter total hours worked today:"
पृच्छ घंटे-मध्ये
५० दर-मध्ये स्थापय  // 50 Rupees per hour base rate

यदि ( घंटे > ८ ) {
    ८ दर गुणय मूल_वेतन-मध्ये
    घंटे ८ न्यूनय अतिरिक्त_घंटे-मध्ये
    ७५ अतिरिक्त_दर-मध्ये स्थापय // Overtime rate

    अतिरिक्त_घंटे अतिरिक्त_दर गुणय अतिरिक्त_वेतन-मध्ये
    मूल_वेतन अतिरिक्त_वेतन संयोजय कुल_वेतन-मध्ये

    वद "Base Wage: " मूल_वेतन " + Overtime: " अतिरिक्त_वेतन
    वद "Total Payout: " कुल_वेतन
} तर्हि {
    घंटे दर गुणय कुल_वेतन-मध्ये
    वद "Total Payout: " कुल_वेतन
}

// 15: Daily Calorie Limit Checker
२००० लक्ष्य-मध्ये स्थापय
० खाया-मध्ये स्थापय
१ चालू-मध्ये स्थापय

वद "Your daily goal is 2000 calories."

यावत् ( चालू == १ ) {
    वद "Enter meal calories (or type 0 to stop):"
    पृच्छ भोजन-मध्ये

    यदि ( भोजन == ० ) {
        ० चालू-मध्ये स्थापय
    } तर्हि {
        खाया भोजन संयोजय खाया-मध्ये
        वद "Total consumed so far: " खाया
    }
}

यदि ( खाया > लक्ष्य ) {
    वद "Warning! You exceeded your daily calorie goal."
} तर्हि {
    वद "Great job staying healthy!"
}

// 16: Resort Booking with Group Discount
वद "Welcome to the Resort Booking System."
वद "Enter number of guests:"
पृच्छ अतिथि-मध्ये
१५०० किराया-मध्ये स्थापय // 1500 per person

अतिथि किराया गुणय कुल_बिल-मध्ये

यदि ( अतिथि > ५ ) {
    वद "Group of more than 5! Applying 10 percent discount."
    कुल_बिल १० गुणय छूट_अंश-मध्ये
    छूट_अंश १०० विभज छूट-मध्ये
    कुल_बिल छूट न्यूनय अंतिम_बिल-मध्ये
    वद "Your final discounted bill is: " अंतिम_बिल
} तर्हि {
    वद "Your total bill is: " कुल_बिल
}

// 18: Psychometric Aptitude Quiz
० अंक-मध्ये स्थापय

वद "Question 1: What is 12 multiplied by 12?"
पृच्छ उत्तर१-मध्ये
यदि ( उत्तर१ == १४४ ) {
    अंक १ संयोजय अंक-मध्ये
    वद "Correct!"
} तर्हि { 
    वद "Wrong." 
}

वद "Question 2: What is 100 divided by 4?"
पृच्छ उत्तर२-मध्ये
यदि ( उत्तर२ == २५ ) {
    अंक १ संयोजय अंक-मध्ये
    वद "Correct!"
} तर्हि { 
    वद "Wrong." 
}

वद "Test complete. Your Aptitude Score is: " अंक "/ 2"

// 19: Astronomical Leap Year Checker
वद "Enter a year to check if it is a Leap Year:"
पृच्छ वर्ष-मध्ये

// Modulo Trick: If (Year / 4) * 4 == Year, it is divisible by 4!
वर्ष ४ विभज भाग-मध्ये 
भाग ४ गुणय जांच-मध्ये

यदि ( वर्ष == जांच ) {
    वद वर्ष " is a Leap Year!"
} तर्हि {
    वद वर्ष " is not a Leap Year."
}

// 20: Guess the Secret Number
७ गुप्त-मध्ये स्थापय
० प्रयास-मध्ये स्थापय
१ चालू-मध्ये स्थापय

वद "I am thinking of a number between 1 and 10."

यावत् ( चालू == १ ) {
    पृच्छ अनुमान-मध्ये
    प्रयास १ संयोजय प्रयास-मध्ये

    यदि ( अनुमान == गुप्त ) {
        वद "Correct! You guessed it in " प्रयास " tries."
        ० चालू-मध्ये स्थापय
    } तर्हि {
        यदि ( अनुमान > गुप्त ) {
            वद "Too high! Try again."
        } तर्हि {
            वद "Too low! Try again."
        }
    }
}

// 21: Interactive Vending Machine Menu
वद "Select an item: 1 for Water, 2 for Chips, 3 for Chocolate"
पृच्छ चयन-मध्ये

यदि ( चयन == १ ) {
    वद "Water selected. Price: 20 Rs."
}
यदि ( चयन == २ ) {
    वद "Chips selected. Price: 30 Rs."
}
यदि ( चयन == ३ ) {
    वद "Chocolate selected. Price: 50 Rs."
}
यदि ( चयन < १ ) {
    वद "Invalid selection."
}
यदि ( चयन > ३ ) {
    वद "Invalid selection."
}

