// ==========================================
// PANINI ARCHITECTURE STRESS TEST
// Prime Number Generator & Multi-Layer Logic
// ==========================================

वद "=== PANINI STRESS TEST: PRIME FINDER ==="
वद "Enter upper limit to find prime numbers:"
पृच्छ सीमा-मध्ये

२ वर्तमान-मध्ये स्थापय
० कुल_प्रधान-मध्ये स्थापय

वद "Calculating primes up to limit..."

// Outer Loop: Iterates through numbers from 2 up to 'सीमा'
यावत् ( वर्तमान < सीमा ) {

    // Assume current number is prime (1 = True, 0 = False)
    १ अस्ति_प्रधान-मध्ये स्थापय
    २ विभाजक-मध्ये स्थापय

    // Inner Loop: Check for factors from 2 up to (वर्तमान / 2)
    // We compute halfway mark to save execution cycles
    वर्तमान २ विभज आधा_वर्तमान-मध्ये

    यावत् ( विभाजक <= आधा_वर्तमान ) {

        // Advanced Math Check: (वर्तमान / विभाजक) * विभाजक == वर्तमान
        वर्तमान विभाजक विभज भाग-मध्ये
        भाग विभाजक गुणय गुणन-मध्ये

        यदि ( वर्तमान == गुणन ) {
            // Factor found! It is NOT a prime number.
            ० अस्ति_प्रधान-मध्ये स्थापय
            // Force inner loop to break by setting divisor higher than limit
            वर्तमान विभाजक-मध्ये स्थापय 
        }

        विभाजक १ संयोजय विभाजक-मध्ये
    }

    // If it survived the inner loop as prime, print and count it
    यदि ( अस्ति_प्रधान == १ ) {
        वद "Found Prime: " वर्तमान
        कुल_प्रधान १ संयोजय कुल_प्रधान-मध्ये
    }

    वर्तमान १ संयोजय वर्तमान-मध्ये
}

वद "=========================================="
वद "Stress test complete!"
वद "Total prime numbers found: " कुल_प्रधान

// 23: Perfect Number Checker
वद "Enter a number to check if it is Perfect:"
पृच्छ संख्या-मध्ये
० योग-मध्ये स्थापय
१ विभाजक-मध्ये स्थापय
संख्या २ विभज आधा-मध्ये

यावत् ( विभाजक <= आधा ) {
    संख्या विभाजक विभज भाग-मध्ये
    भाग विभाजक गुणय गुणन-मध्ये

    यदि ( संख्या == गुणन ) {
        योग विभाजक संयोजय योग-मध्ये
    }
    विभाजक १ संयोजय विभाजक-मध्ये
}
यदि ( योग == संख्या ) {
    वद संख्या " is a PERFECT Number!"
} तर्हि {
    वद संख्या " is not perfect."
}

// 25: Collatz Peak Tracker
वद "Enter Collatz starting number:"
पृच्छ वर्तमान-मध्ये
० अधिकतम-मध्ये स्थापय
० कदम-मध्ये स्थापय

यावत् ( वर्तमान > १ ) {
    यदि ( वर्तमान > अधिकतम ) {
        वर्तमान अधिकतम-मध्ये स्थापय
    }

    वर्तमान २ विभज आधा-मध्ये
    आधा २ गुणय सम_जांच-मध्ये

    यदि ( वर्तमान == सम_जांच ) {
        आधा वर्तमान-मध्ये स्थापय
    } तर्हि {
        वर्तमान ३ गुणय वर्तमान-मध्ये
        वर्तमान १ संयोजय वर्तमान-मध्ये
    }
    कदम १ संयोजय कदम-मध्ये
}
वद "Reached 1 in " कदम " steps!"
वद "Peak value reached: " अधिकतम

// 26: Prime Factorization
वद "Enter a number to factorize:"
पृच्छ संख्या-मध्ये
२ विभाजक-मध्ये स्थापय

यावत् ( संख्या > १ ) {
    संख्या विभाजक विभज भाग-मध्ये
    भाग विभाजक गुणय गुणन-मध्ये

    यदि ( संख्या == गुणन ) {
        वद "Factor: " विभाजक
        भाग संख्या-मध्ये स्थापय
    } तर्हि {
        विभाजक १ संयोजय विभाजक-मध्ये
    }
}

// 27: Digital Root (Sum of sums)
वद "Enter a large number:"
पृच्छ संख्या-मध्ये

यावत् ( संख्या > ९ ) {
    ० योग-मध्ये स्थापय

    यावत् ( संख्या > ० ) {
        संख्या १० विभज भाग-मध्ये
        भाग १० गुणय गुणन-मध्ये
        संख्या गुणन न्यूनय शेष-मध्ये

        योग शेष संयोजय योग-मध्ये
        भाग संख्या-मध्ये स्थापय
    }
    योग संख्या-मध्ये स्थापय
}
वद "The Digital Root is: " संख्या

// 28: Median of Three Numbers
वद "Enter A:"
पृच्छ अ-मध्ये
वद "Enter B:"
पृच्छ ब-मध्ये
वद "Enter C:"
पृच्छ स-मध्ये

यदि ( अ > ब ) {
    यदि ( ब > स ) { वद "Median is B: " ब }
    तर्हि {
        यदि ( अ > स ) { वद "Median is C: " स }
        तर्हि { वद "Median is A: " अ }
    }
} तर्हि {
    यदि ( अ > स ) { वद "Median is A: " अ }
    तर्हि {
        यदि ( ब > स ) { वद "Median is C: " स }
        तर्हि { वद "Median is B: " ब }
    }
}

// 29: Progressive Tax Calculator
वद "Enter Income:"
पृच्छ आय-मध्ये
० कर-मध्ये स्थापय

यदि ( आय > १००००० ) {
    आय १००००० न्यूनय शेष-मध्ये
    शेष ०.३ गुणय अतिरिक्त-मध्ये
    कर अतिरिक्त संयोजय कर-मध्ये
    १००००० आय-मध्ये स्थापय
}
यदि ( आय > ५०००० ) {
    आय ५०००० न्यूनय शेष-मध्ये
    शेष ०.२ गुणय अतिरिक्त-मध्ये
    कर अतिरिक्त संयोजय कर-मध्ये
    ५०००० आय-मध्ये स्थापय
}
यदि ( आय > २०००० ) {
    आय २०००० न्यूनय शेष-मध्ये
    शेष ०.१ गुणय अतिरिक्त-मध्ये
    कर अतिरिक्त संयोजय कर-मध्ये
}
वद "Total Tax Owed: " कर

// 30: Single Digit to String Switcher
वद "Enter a single digit (0-5):"
पृच्छ अंक-मध्ये

यदि ( अंक == ० ) { वद "Zero" }
यदि ( अंक == १ ) { वद "One" }
यदि ( अंक == २ ) { वद "Two" }
यदि ( अंक == ३ ) { वद "Three" }
यदि ( अंक == ४ ) { वद "Four" }
यदि ( अंक == ५ ) { वद "Five" }
यदि ( अंक > ५ ) { वद "Number too big for this demo!" }

// 31: Pythagorean Triplets (A^2 + B^2 = C^2)
वद "Finding triplets up to limit 15..."
१५ सीमा-मध्ये स्थापय
१ अ-मध्ये स्थापय

यावत् ( अ <= सीमा ) {
    अ अ गुणय अ_वर्ग-मध्ये
    १ ब-मध्ये स्थापय

    यावत् ( ब <= सीमा ) {
        ब ब गुणय ब_वर्ग-मध्ये
        १ स-मध्ये स्थापय

        यावत् ( स <= सीमा ) {
            स स गुणय स_वर्ग-मध्ये
            अ_वर्ग ब_वर्ग संयोजय योग-मध्ये

            यदि ( योग == स_वर्ग ) {
                वद "Triplet found: " अ ", " ब ", " स
            }
            स १ संयोजय स-मध्ये
        }
        ब १ संयोजय ब-मध्ये
    }
    अ १ संयोजय अ-मध्ये
}

// 32: Decimal to Binary String
वद "Enter number to convert to Binary:"
पृच्छ संख्या-मध्ये
"" बाइनरी-मध्ये स्थापय

यावत् ( संख्या > ० ) {
    संख्या २ विभज भाग-मध्ये
    भाग २ गुणय गुणन-मध्ये
    संख्या गुणन न्यूनय शेष-मध्ये

    // Prepend remainder to string
    शेष बाइनरी संयोजय बाइनरी-मध्ये
    भाग संख्या-मध्ये स्थापय
}
वद "Binary Output: " बाइनरी

// 34: Star Pyramid Generator
वद "Enter pyramid height:"
पृच्छ ऊंचाई-मध्ये
१ पंक्ति-मध्ये स्थापय

यावत् ( पंक्ति <= ऊंचाई ) {
    "" सितारे-मध्ये स्थापय
    १ गिनती-मध्ये स्थापय

    यावत् ( गिनती <= पंक्ति ) {
        सितारे "*" संयोजय सितारे-मध्ये
        गिनती १ संयोजय गिनती-मध्ये
    }
    वद सितारे
    पंक्ति १ संयोजय पंक्ति-मध्ये
}

// 38: Armstrong Number Checker
वद "Enter a 3-digit number:"
पृच्छ संख्या-मध्ये
संख्या मूल-मध्ये स्थापय
० योग-मध्ये स्थापय

यावत् ( संख्या > ० ) {
    संख्या १० विभज भाग-मध्ये
    भाग १० गुणय गुणन-मध्ये
    संख्या गुणन न्यूनय शेष-मध्ये

    शेष शेष गुणय वर्ग-मध्ये
    वर्ग शेष गुणय घन-मध्ये
    योग घन संयोजय योग-मध्ये

    भाग संख्या-मध्ये स्थापय
}
यदि ( योग == मूल ) {
    वद मूल " IS an Armstrong Number!"
} तर्हि {
    वद मूल " is NOT an Armstrong Number."
}

// 40: The Safety Governor Test
वद "Attempting to run an infinite loop..."
वद "The compiler should forcefully stop at 2000 steps."
१ चालू-मध्ये स्थापय
० गिनती-मध्ये स्थापय

यावत् ( चालू == १ ) {
    गिनती १ संयोजय गिनती-मध्ये
    // Intentionally never turning 'चालू' to 0
}
वद "Governor activated! Loop stopped safely."
वद "Total steps executed: " गिनती

// 42: Self-Dividing Numbers (e.g. 128 is divisible by 1, 2, and 8)
वद "Checking number 128:"
१२८ संख्या-मध्ये स्थापय
संख्या वर्तमान-मध्ये स्थापय
१ सफल-मध्ये स्थापय

यावत् ( वर्तमान > ० ) {
    वर्तमान १० विभज भाग-मध्ये
    भाग १० गुणय गुणन-मध्ये
    वर्तमान गुणन न्यूनय शेष-मध्ये

    यदि ( शेष == ० ) {
        ० सफल-मध्ये स्थापय
    } तर्हि {
        संख्या शेष विभज जांच_भाग-मध्ये
        जांच_भाग शेष गुणय जांच_गुणन-मध्ये
        यदि ( संख्या != जांच_गुणन ) {
            ० सफल-मध्ये स्थापय
        }
    }
    भाग वर्तमान-मध्ये स्थापय
}

यदि ( सफल == १ ) { वद संख्या " is Self-Dividing!" }
तर्हि { वद संख्या " is NOT Self-Dividing." }
